// Generated by `npm run gen-index`. Do not edit by hand.
import { catalog, bySlug } from "../catalog.js";
import { buildProblem } from "../../lib/problem.js";

const loaders = {
  "two-sum": () => Promise.all([import("./two-sum.js"), import("../expected/two-sum.json")]),
  "valid-parentheses": () => Promise.all([import("./valid-parentheses.js"), import("../expected/valid-parentheses.json")]),
  "min-stack": () => Promise.all([import("./min-stack.js"), import("../expected/min-stack.json")]),
  "reverse-linked-list": () => Promise.all([import("./reverse-linked-list.js"), import("../expected/reverse-linked-list.json")]),
  "maximum-depth-of-binary-tree": () => Promise.all([import("./maximum-depth-of-binary-tree.js"), import("../expected/maximum-depth-of-binary-tree.json")]),
};

// Metadata for every available problem, in sheet order (for the dashboard).
export const problems = catalog.filter((p) => p.slug in loaders);

export function hasProblem(slug) {
  return slug in loaders;
}

export async function getProblem(slug) {
  if (!(slug in loaders)) return null;
  const [mod, expected] = await loaders[slug]();
  return buildProblem(bySlug[slug], mod.default, expected.default);
}
